// Meetup member roster (moderators). RLS on meetup_members / meetup_rsvps enforces moderator-only server-side.
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { ActivityIndicator, FlatList, RefreshControl, Text, View } from 'react-native';
import { Redirect, router } from 'expo-router';
import { Button, EmptyState, ErrorText, ListColumnHeader, ListRow, Page, PageHeader, Segmented, Toolbar, styles, type Column } from '../../../components/ui';
import { useCanModerate } from '../../../components/mod';
import { MEETUP_MEMBER_PAGE_SIZE, listMeetupMembers, syncMeetupMembers, type MeetupMember, type MeetupMemberSort } from '../../../lib/api';
import { trackAppEvent } from '../../../lib/analytics';
import { colors, fs } from '../../../lib/theme';

const COLS: Column[] = [{ label: 'Member', flex: 2 }, { label: 'Joined', width: 96 }, { label: 'RSVPs', width: 56, align: 'right' }, { label: 'Attended', width: 70, align: 'right' }];
const PAGE = MEETUP_MEMBER_PAGE_SIZE;
const day = (iso: string | null) => (iso ? new Date(iso).toLocaleDateString() : '—');
const memberLabel = (m: MeetupMember) => (m.profile_name && m.profile_name !== m.name ? `${m.name ?? '(no name)'} · ${m.profile_name}` : (m.name ?? '(no name)'));

export default function MembersTab() {
  const { ready, ok } = useCanModerate();
  const [items, setItems] = useState<MeetupMember[]>([]);
  const [q, setQ] = useState('');
  const [debouncedQ, setDebouncedQ] = useState('');
  const [sort, setSort] = useState<MeetupMemberSort>('name');
  const [linkedOnly, setLinkedOnly] = useState(false);
  const [total, setTotal] = useState<number | null>(null);
  const [linked, setLinked] = useState<number | null>(null);
  const [matchCount, setMatchCount] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  const generation = useRef(0);
  const paging = useRef(false);
  const firstLoad = useRef(false);
  const scrolled = useRef(false);
  const nextOffset = useRef(0);
  const listRef = useRef<FlatList<MeetupMember>>(null);
  const itemsRef = useRef(items);
  const matchRef = useRef(matchCount);
  const hasMoreRef = useRef(false);
  const queryRef = useRef({ search: debouncedQ, sort, linkedOnly });
  itemsRef.current = items;
  matchRef.current = matchCount;
  hasMoreRef.current = matchCount != null && items.length < matchCount;
  queryRef.current = { search: debouncedQ, sort, linkedOnly };

  useEffect(() => {
    const t = setTimeout(() => setDebouncedQ(q.trim()), 250);
    return () => clearTimeout(t);
  }, [q]);

  const loadFirstPage = useCallback(async (refresh = false) => {
    const gen = ++generation.current;
    const search = debouncedQ;
    paging.current = false;
    firstLoad.current = true;
    scrolled.current = false;
    nextOffset.current = 0;
    setErr(null);
    setLoadingMore(false);
    setRefreshing(refresh);
    setLoading(!refresh);
    if (!refresh) {
      itemsRef.current = [];
      matchRef.current = null;
      setItems([]);
      setMatchCount(null);
    }
    try {
      const page = await listMeetupMembers({ search, sort, linkedOnly, offset: 0, limit: PAGE });
      if (generation.current !== gen) return;
      itemsRef.current = page.members;
      matchRef.current = page.matchCount;
      nextOffset.current = page.members.length < PAGE ? page.members.length : PAGE;
      setItems(page.members);
      setMatchCount(page.matchCount);
      setTotal(page.total);
      setLinked(page.linked);
      listRef.current?.scrollToOffset({ offset: 0, animated: false });
      scrolled.current = false;
    } catch (e: any) {
      if (generation.current !== gen) return;
      setErr(e.message ?? 'Couldn’t load members.');
    } finally {
      if (generation.current === gen) {
        firstLoad.current = false;
        setLoading(false);
        setRefreshing(false);
      }
    }
  }, [debouncedQ, sort, linkedOnly]);

  useEffect(() => {
    if (!ok) return;
    loadFirstPage(false);
    return () => { generation.current += 1; };
  }, [ok, loadFirstPage]);

  const loadMore = useCallback(async () => {
    if (paging.current || firstLoad.current) return;
    const loaded = itemsRef.current.length;
    const match = matchRef.current;
    if (loaded === 0 || (match != null && loaded >= match)) return;
    const gen = generation.current;
    const offset = nextOffset.current;
    const query = queryRef.current;
    paging.current = true;
    setLoadingMore(true);
    try {
      const page = await listMeetupMembers({ ...query, offset, limit: PAGE, counts: false });
      if (generation.current !== gen) return;
      const prev = itemsRef.current;
      const seen = new Set(prev.map((m) => m.meetup_member_id));
      const next = page.members.filter((m) => !seen.has(m.meetup_member_id));
      const merged = next.length ? [...prev, ...next] : prev;
      if (next.length === 0 || page.members.length < PAGE) {
        matchRef.current = merged.length;
        setMatchCount(merged.length);
      }
      itemsRef.current = merged;
      nextOffset.current = page.members.length < PAGE ? offset + page.members.length : offset + PAGE;
      if (next.length) setItems(merged);
    } catch (e: any) {
      if (generation.current === gen) setErr(e.message ?? 'Couldn’t load more members.');
    } finally {
      if (generation.current === gen) {
        paging.current = false;
        setLoadingMore(false);
      }
    }
  }, []);

  const sync = async () => {
    setBusy(true); setErr(null); setMsg('Syncing members…');
    try {
      let r = await syncMeetupMembers({ members: true, rsvps: true });
      let events = r.rsvpEvents ?? 0, rsvps = r.rsvps ?? 0;
      // RSVPs sync in batches of events; keep going until caught up (bounded).
      for (let i = 0; i < 20 && (r.remaining ?? 0) > 0; i++) {
        setMsg(`Synced ${events} events' RSVPs, ${r.remaining} to go…`);
        r = await syncMeetupMembers({ members: false, rsvps: true });
        events += r.rsvpEvents ?? 0; rsvps += r.rsvps ?? 0;
      }
      trackAppEvent('sync_meetup', { scope: 'members' }, { key: 'sync_meetup:members', ms: 2000 });
      setMsg(`Synced members and ${rsvps} RSVPs across ${events} events.${r.remaining ? ` ${r.remaining} events left. Sync again to continue.` : ''}`);
      await loadFirstPage(true);
    } catch (e: any) { setErr(e.message); setMsg(null); } finally { setBusy(false); }
  };

  if (!ready) return <View style={{ flex: 1, backgroundColor: colors.paper }} />;
  if (!ok) return <Redirect href="/chat" />;

  const hasMore = matchCount != null && items.length < matchCount;
  const remaining = hasMore ? matchCount - items.length : 0;
  const untouched = !debouncedQ && !linkedOnly && (total ?? 0) === 0;
  return (
    <Page scroll={false} fill>
      <Text onPress={() => router.navigate('/chat')} accessibilityRole="link" style={[styles.link, { fontSize: fs(13) }]}>Back to chat</Text>
      <PageHeader icon="people" title="Meetup members"
        subtitle={total == null ? 'Reading Fellowship roster from Meetup' : `${total} members · ${linked ?? 0} on the app`}
        actions={<Button small icon="sync" title={busy ? 'Syncing…' : 'Sync'} disabled={busy} onPress={sync} />} />
      <Toolbar search={q} onSearch={setQ} placeholder="Search name or city…">
        <Segmented<MeetupMemberSort> value={sort} onChange={setSort} options={[{ value: 'name', label: 'Name' }, { value: 'attended', label: 'Most active' }, { value: 'recent', label: 'Recent' }, { value: 'joined', label: 'Newest' }]} />
        <Button small variant="neutral" icon="link-outline" title={linkedOnly ? 'All members' : 'On the app'} onPress={() => setLinkedOnly(!linkedOnly)} />
      </Toolbar>
      {msg ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{msg}</Text> : null}
      <ErrorText>{err}</ErrorText>
      <View style={[styles.listCard, { flex: 1, minHeight: 0 }]}>
        <View style={styles.listTitle}>
          <Text style={styles.sectionTitle}>Roster</Text>
          {matchCount != null ? <Text style={[styles.muted, { fontSize: fs(12) }]}>{matchCount} {matchCount === 1 ? 'item' : 'items'}</Text> : null}
        </View>
        {items.length > 0 ? <ListColumnHeader columns={COLS} /> : null}
        <FlatList
          ref={listRef}
          style={{ flex: 1 }}
          data={items}
          keyExtractor={(m) => m.meetup_member_id}
          renderItem={({ item }) => (
            <ListRow columns={COLS} accessibilityLabel={memberLabel(item)} onPress={() => router.push(`/meetup/member/${encodeURIComponent(item.meetup_member_id)}`)}
              cells={[memberLabel(item), day(item.joined_at), item.rsvp_yes, item.attended]} />
          )}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => loadFirstPage(true)} />}
          keyboardShouldPersistTaps="handled"
          scrollEventThrottle={16}
          onScroll={(e) => { scrolled.current = e.nativeEvent.contentOffset.y > 24; }}
          onEndReached={() => { if (scrolled.current && hasMoreRef.current) loadMore(); }}
          onEndReachedThreshold={0.4}
          ListEmptyComponent={loading ? (
            <View style={{ padding: 20 }}><ActivityIndicator color={colors.navy} /></View>
          ) : err ? (
            <View />
          ) : (
            <EmptyState icon="people-outline" title={untouched ? 'No members synced yet' : 'No matches'} body={untouched ? 'Use Sync to pull the roster and RSVPs from Meetup.' : undefined} />
          )}
          ListFooterComponent={hasMore ? (
            <View style={{ padding: 12, alignItems: 'center' }}>
              {loadingMore ? <ActivityIndicator color={colors.navy} /> : <Button small variant="neutral" title={`Show more (${remaining} left)`} disabled={refreshing} onPress={loadMore} />}
            </View>
          ) : <View style={{ height: 8 }} />}
        />
      </View>
    </Page>
  );
}
